/**
 * FERN-JOB-MANIFEST – Vertrag zwischen Editor und externem Worker (§17–§19, §22, §34).
 *
 * Der Fernpfad (High Quality extern) transportiert Jobs über einen
 * Google-Drive-Ordner. Was dabei über die Grenze geht, muss **prüfbar** sein:
 * eine unbekannte Schema-Version, eine fremde Job-Id, ein Pfad außerhalb der
 * Jobwurzel oder ein „COMPLETED“ mit fehlenden Stems darf niemals still
 * durchgehen. Genau diese Fälle stehen hier – ohne Netz, ohne Drive, ohne
 * Modell, weil es reine Protokolllogik ist.
 *
 *   1. Manifest bauen: UUID, Zeiten, Schema, Idempotenzschlüssel
 *   2. Fremde/kaputte Manifeste werden abgelehnt (kein Ratemodus)
 *   3. Idempotenz: gleicher Input + gleiches Modell ⇒ gleicher Schlüssel,
 *      anderes Profil/Modell ⇒ anderer Schlüssel (§19)
 *   4. „COMPLETED“ ohne alle Stems ist kein Erfolg (§34 K)
 *   5. Leere/fehlende Outputs sind kein Erfolg (§34 I/J)
 *   6. Layout: Pfade bleiben in der Jobwurzel (kein Ausbruch aus der Ablage)
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import {
  buildManifest,
  buildResultDocument,
  createRemoteJobId,
  idempotencyKeyFor,
  parseManifest,
  serializeManifest,
  verifyCompletedManifest,
  withStatus,
  RemoteProtocolError,
} from '../src/stems/remote/manifest';
import {
  assertSafeRelative,
  jobInputPath,
  jobManifestPath,
  jobOutputPath,
  isSafeJobId,
  stemFileName,
} from '../src/stems/remote/layout';
import { REMOTE_JOB_SCHEMA_VERSION } from '../src/stems/remote/types';

console.log('═══════════════════════════════════════════════════════════════════');
console.log('  FERN-JOB-MANIFEST – SCHEMA, IDEMPOTENZ, VOLLSTÄNDIGKEIT         ');
console.log('═══════════════════════════════════════════════════════════════════');

function baseManifest(jobId = createRemoteJobId()) {
  return buildManifest({
    jobId,
    trackName: 'track_abc',
    appVersion: '0.4.2',
    input: {
      fileName: 'track_abc.wav',
      relativePath: jobInputPath(jobId, 'track_abc.wav'),
      sha256: 'a'.repeat(64),
      bytes: 1_234_567,
      durationSeconds: 300,
      sampleRate: 44100,
      channels: 2,
    },
    engine: {
      backend: 'bs_roformer',
      family: 'bs_roformer',
      modelId: 'bsroformer-musdb18hq-4stem-zfturbo',
      profile: 'HIGH_QUALITY',
      stems: ['drums', 'bass', 'other', 'vocals'],
      device: 'auto',
    },
    idempotencyKey: idempotencyKeyFor({
      sha256: 'a'.repeat(64),
      modelId: 'bsroformer-musdb18hq-4stem-zfturbo',
      profile: 'HIGH_QUALITY',
    }),
  });
}

async function run() {
  // =========================================================================
  console.log('\n[ TEST ] #1 Manifest bauen: Schema, Id, Zeiten, Idempotenzschlüssel');
  const manifest = baseManifest();
  assert.equal(manifest.schemaVersion, REMOTE_JOB_SCHEMA_VERSION);
  assert.match(manifest.jobId, /^[0-9a-f-]{36}$/, 'Job-Id ist eine UUID, nicht der Dateiname (§18)');
  assert.equal(manifest.status, 'PENDING');
  assert.equal(manifest.output.stems.length, 0);
  assert.equal(manifest.createdAtIso.endsWith('Z'), true, 'zusätzlich ISO-Zeit für Colab/Menschen');
  const roundTrip = parseManifest(serializeManifest(manifest), manifest.jobId);
  assert.deepEqual(roundTrip.input, manifest.input);
  assert.deepEqual(roundTrip.engine.stems, ['drums', 'bass', 'other', 'vocals']);
  const sharedFixture = readFileSync(new URL('./fixtures/stem-remote-manifest-v1.json', import.meta.url), 'utf8');
  const fixtureManifest = parseManifest(sharedFixture, '00000000-0000-4000-8000-000000000001');
  assert.equal(fixtureManifest.schemaVersion, REMOTE_JOB_SCHEMA_VERSION);
  assert.deepEqual(fixtureManifest.engine.stems, ['drums', 'bass', 'other', 'vocals']);
  console.log(`  ✓ Manifest ${manifest.jobId.slice(0, 8)}… serialisiert und wieder gelesen`);
  console.log('  ✓ Gemeinsame v1-Fixture wird vom TypeScript-Editor akzeptiert');

  // =========================================================================
  console.log('\n[ TEST ] #2 Kaputte/fremde Manifeste werden abgelehnt');
  const wrongSchema = JSON.stringify({ ...manifest, schemaVersion: 99 });
  assert.throws(
    () => parseManifest(wrongSchema),
    (error: unknown) => error instanceof RemoteProtocolError && error.code === 'REMOTE_SCHEMA_UNSUPPORTED',
    'unbekanntes Schema muss hart scheitern'
  );
  assert.throws(
    () => parseManifest(JSON.stringify(manifest), createRemoteJobId()),
    (error: unknown) => error instanceof RemoteProtocolError && error.code === 'REMOTE_MANIFEST_INVALID',
    'Manifest-Id ≠ Verzeichnis-Id muss abgelehnt werden'
  );
  assert.throws(() => parseManifest('{kein json'), (error: unknown) => error instanceof RemoteProtocolError);
  const traversal = JSON.stringify({
    ...manifest,
    input: { ...manifest.input, relativePath: '../../etc/passwd' },
  });
  assert.throws(
    () => parseManifest(traversal),
    'ein Manifest darf nicht aus der Jobablage hinauszeigen'
  );
  assert.throws(() => assertSafeRelative('/absolut/wav.wav'));
  assert.throws(() => assertSafeRelative('jobs\\..\\x.wav'));
  assert.equal(isSafeJobId('../../x'), false);
  assert.equal(isSafeJobId(createRemoteJobId()), true);
  console.log('  ✓ Schema, Id-Abgleich, Pfad-Ausbruch und JSON-Fehler sind harte Fehler');

  // =========================================================================
  console.log('\n[ TEST ] #3 Idempotenzschlüssel: gleiche Arbeit ⇒ gleicher Schlüssel (§19)');
  const same = idempotencyKeyFor({ sha256: 'b'.repeat(64), modelId: 'm1', profile: 'HIGH_QUALITY' });
  assert.equal(same, idempotencyKeyFor({ sha256: 'b'.repeat(64), modelId: 'm1', profile: 'HIGH_QUALITY' }));
  assert.notEqual(same, idempotencyKeyFor({ sha256: 'c'.repeat(64), modelId: 'm1', profile: 'HIGH_QUALITY' }));
  assert.notEqual(same, idempotencyKeyFor({ sha256: 'b'.repeat(64), modelId: 'm1', profile: 'MAXIMUM_QUALITY' }));
  assert.notEqual(same, idempotencyKeyFor({ sha256: 'b'.repeat(64), modelId: 'm2', profile: 'HIGH_QUALITY' }));
  console.log('  ✓ Schlüssel hängt an Input-Hash, Modell und Profil – nicht an Dateinamen oder Zeit');

  // =========================================================================
  console.log('\n[ TEST ] #4 „COMPLETED“ ohne alle Stems ist kein Erfolg (§34 K)');
  const incomplete = withStatus(manifest, {
    status: 'COMPLETED',
    output: {
      stems: [
        { id: 'drums', fileName: 'drums.wav', relativePath: jobOutputPath(manifest.jobId, 'drums.wav'), sha256: 'd'.repeat(64), bytes: 1000, frames: 10, sampleRate: 44100, channels: 2 },
      ],
    },
  });
  const incompleteCheck = verifyCompletedManifest(incomplete);
  assert.equal(incompleteCheck.ok, false);
  assert.equal(incompleteCheck.ok === false && incompleteCheck.code, 'REMOTE_OUTPUT_INCOMPLETE');
  assert.match(incompleteCheck.ok === false ? incompleteCheck.message : '', /bass, other, vocals/);
  console.log('  ✓ fehlende Stems ⇒ REMOTE_OUTPUT_INCOMPLETE mit Klartext-Liste');

  // =========================================================================
  console.log('\n[ TEST ] #5 Leere Outputs sind kein Erfolg (§34 I/J)');
  const stems = ['drums', 'bass', 'other', 'vocals'].map((id) => ({
    id,
    fileName: stemFileName(id),
    relativePath: jobOutputPath(manifest.jobId, stemFileName(id)),
    sha256: 'e'.repeat(64),
    bytes: id === 'vocals' ? 44 : 4096,
    frames: 100,
    sampleRate: 44100,
    channels: 2,
  }));
  const emptyCheck = verifyCompletedManifest(withStatus(manifest, { status: 'COMPLETED', output: { stems } }));
  assert.equal(emptyCheck.ok, false);
  assert.equal(emptyCheck.ok === false && emptyCheck.code, 'REMOTE_OUTPUT_EMPTY');
  const goodCheck = verifyCompletedManifest(
    withStatus(manifest, { status: 'COMPLETED', output: { stems: stems.map((stem) => ({ ...stem, bytes: 4096 })) } })
  );
  assert.equal(goodCheck.ok, true, 'erst mit allen vier nicht-leeren Stems ist der Job fertig');
  assert.equal(verifyCompletedManifest(manifest).ok, false, 'RUNNING ist nicht COMPLETED');
  console.log('  ✓ 44-Byte-„WAV“ zählt nicht als Stem; Vollständigkeit wird erzwungen');

  // =========================================================================
  console.log('\n[ TEST ] #6 Layout bleibt in der Ablage; Ergebnisdokument ist lesbar');
  assert.equal(jobManifestPath('job-12345678'), 'jobs/job-12345678/manifest.json');
  // Ein Pfad im Dateinamen wird auf den Basisnamen reduziert: kein Verzeichnis
  // kann aus der Jobablage herausführen, Sonderzeichen werden ersetzt.
  assert.equal(jobInputPath('job-12345678', 'a b/c?.wav'), 'jobs/job-12345678/input/c_.wav');
  assert.equal(jobInputPath('job-12345678', '../../x.wav'), 'jobs/job-12345678/input/x.wav');
  assert.equal(stemFileName('vocals'), 'vocals.wav');
  const doc = JSON.parse(buildResultDocument(withStatus(manifest, { status: 'COMPLETED', output: { stems } }))) as {
    jobId: string;
    stems: { id: string }[];
  };
  assert.equal(doc.jobId, manifest.jobId);
  assert.deepEqual(doc.stems.map((stem) => stem.id), ['drums', 'bass', 'other', 'vocals']);
  console.log('  ✓ Pfade normalisiert, Ergebnisdokument trägt Job-Id und Stem-Liste');

  console.log('\n═══════════════════════════════════════════════════════════════════');
  console.log('  ALLE MANIFEST-PRÜFUNGEN BESTANDEN');
  console.log('═══════════════════════════════════════════════════════════════════');
}

run().catch((error) => {
  console.error(error);
  process.exit(1);
});

/**
 * Job-Manifest: bauen, serialisieren, prüfen (§17, §22, §34).
 *
 * Das Manifest ist die einzige Quelle der Wahrheit über einen Fern-Job. Beide
 * Seiten (Editor und Worker) schreiben es – deshalb wird beim **Lesen** streng
 * validiert: eine unbekannte Schema-Version, eine fehlende Id oder ein Pfad,
 * der aus der Job-Wurzel führt, sind harte Fehler und keine Warnung. Ein Job,
 * der nicht sauber gelesen werden kann, gilt als fehlgeschlagen, nicht als
 * „irgendwie fertig“.
 */
import { createHash, randomUUID } from 'node:crypto';
import type {
  ModelFamily,
  QualityProfile,
  StemId,
} from '../types';
import type {
  RemoteJobEngineRef,
  RemoteJobInput,
  RemoteJobManifest,
  RemoteJobStatus,
  RemoteStemOutput,
} from './types';
import { REMOTE_JOB_SCHEMA_VERSION } from './types';
import { assertSafeRelative, isSafeJobId } from './layout';

/** Maschinenlesbare Fehler des Fern-Protokolls. */
export class RemoteProtocolError extends Error {
  readonly code: string;
  readonly details?: Record<string, unknown>;
  constructor(code: string, message: string, details?: Record<string, unknown>) {
    super(message);
    this.name = 'RemoteProtocolError';
    this.code = code;
    this.details = details;
  }
}

export const REMOTE_STATUSES: RemoteJobStatus[] = [
  'PENDING',
  'PREPARING',
  'RUNNING',
  'RECONSTRUCTING',
  'VALIDATING',
  'COMPLETED',
  'CANCELLED',
  'FAILED',
];

export const TERMINAL_STATUSES: RemoteJobStatus[] = ['COMPLETED', 'FAILED', 'CANCELLED'];

export function isTerminalStatus(status: RemoteJobStatus): boolean {
  return TERMINAL_STATUSES.includes(status);
}

/** Neue Job-Id: UUID, nicht Dateiname (§18). */
export function createRemoteJobId(): string {
  return randomUUID();
}

/**
 * Idempotenzschlüssel (§19): gleicher Input-Hash + gleiches Modell + gleiches
 * Profil = dieselbe Arbeit. Der Editor legt dafür keinen zweiten Job an,
 * unabhängig davon, wie oft neu gepollt, neu gestartet oder neu geklickt wird.
 */
export function idempotencyKeyFor(input: {
  sha256: string;
  modelId: string;
  profile: QualityProfile;
  family?: ModelFamily;
  stems?: StemId[];
}): string {
  const material = [input.sha256, input.modelId, input.profile, input.family ?? '', (input.stems ?? []).join(',')].join('|');
  return createHash('sha256').update(material).digest('hex');
}

export function buildManifest(input: {
  jobId: string;
  trackName: string;
  appVersion: string;
  host?: string;
  input: RemoteJobInput;
  engine: RemoteJobEngineRef;
  idempotencyKey: string;
  status?: RemoteJobStatus;
  phase?: string;
}): RemoteJobManifest {
  const now = Date.now();
  return {
    schemaVersion: REMOTE_JOB_SCHEMA_VERSION,
    jobId: input.jobId,
    createdAt: now,
    updatedAt: now,
    createdAtIso: new Date(now).toISOString(),
    updatedAtIso: new Date(now).toISOString(),
    status: input.status ?? 'PENDING',
    phase: input.phase,
    percent: 0,
    idempotencyKey: input.idempotencyKey,
    origin: { app: 'airdox_SMART_Editor', version: input.appVersion, host: input.host },
    input: input.input,
    engine: input.engine,
    output: { stems: [] },
    attempts: 0,
    notes: [`track=${input.trackName}`],
  };
}

/** Aktualisiert Status/Phase/Worker und stempelt `updatedAt` neu. */
export function withStatus(
  manifest: RemoteJobManifest,
  patch: {
    status?: RemoteJobStatus;
    phase?: string;
    percent?: number;
    worker?: RemoteJobManifest['worker'];
    output?: RemoteJobManifest['output'];
    error?: RemoteJobManifest['error'];
    cancelRequested?: boolean;
    attempts?: number;
    notes?: string[];
  }
): RemoteJobManifest {
  const now = Date.now();
  return {
    ...manifest,
    ...patch,
    status: patch.status ?? manifest.status,
    output: patch.output ?? manifest.output,
    updatedAt: now,
    updatedAtIso: new Date(now).toISOString(),
  };
}

export function serializeManifest(manifest: RemoteJobManifest): string {
  return `${JSON.stringify(manifest, null, 2)}\n`;
}

function requireString(value: unknown, field: string, jobId: string): string {
  if (typeof value !== 'string' || value.length === 0) {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', `Manifest ${jobId}: Feld "${field}" fehlt oder ist leer`);
  }
  return value;
}

/**
 * Liest ein Manifest und prüft es gegen das Schema.
 *
 * `expectedJobId` kommt aus dem Verzeichnisnamen: weicht die Id *im* Manifest
 * davon ab, ist die Ablage inkonsistent (zwei Jobs in einem Ordner) und der
 * Job wird abgelehnt, statt Ergebnisse der falschen Datei zuzuordnen.
 */
export function parseManifest(raw: string | Uint8Array, expectedJobId?: string): RemoteJobManifest {
  let parsed: unknown;
  try {
    parsed = JSON.parse(typeof raw === 'string' ? raw : Buffer.from(raw).toString('utf8'));
  } catch (error) {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', `Manifest ist kein gültiges JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (!parsed || typeof parsed !== 'object') {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', 'Manifest ist kein Objekt');
  }
  const manifest = parsed as RemoteJobManifest;
  if (manifest.schemaVersion !== REMOTE_JOB_SCHEMA_VERSION) {
    throw new RemoteProtocolError(
      'REMOTE_SCHEMA_UNSUPPORTED',
      `Manifest-Schema ${manifest.schemaVersion} wird nicht unterstützt (erwartet ${REMOTE_JOB_SCHEMA_VERSION})`
    );
  }
  if (!isSafeJobId(manifest.jobId)) {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', `Ungültige jobId im Manifest: ${JSON.stringify(manifest.jobId)}`);
  }
  if (expectedJobId && manifest.jobId !== expectedJobId) {
    throw new RemoteProtocolError(
      'REMOTE_MANIFEST_INVALID',
      `Manifest-Id ${manifest.jobId} passt nicht zum Verzeichnis ${expectedJobId}`
    );
  }
  if (!REMOTE_STATUSES.includes(manifest.status)) {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', `Unbekannter Status ${JSON.stringify(manifest.status)}`);
  }
  if (!manifest.input || typeof manifest.input !== 'object') {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', 'Manifest ohne input-Block');
  }
  requireString(manifest.input.sha256, 'input.sha256', manifest.jobId);
  requireString(manifest.input.fileName, 'input.fileName', manifest.jobId);
  assertSafeRelative(manifest.input.relativePath);
  if (!manifest.engine || typeof manifest.engine !== 'object') {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', 'Manifest ohne engine-Block');
  }
  requireString(manifest.engine.modelId, 'engine.modelId', manifest.jobId);
  requireString(manifest.engine.profile, 'engine.profile', manifest.jobId);
  if (!Array.isArray(manifest.engine.stems) || manifest.engine.stems.length === 0) {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', 'Manifest ohne engine.stems');
  }
  const output = manifest.output ?? { stems: [] };
  if (!Array.isArray(output.stems)) {
    throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', 'Manifest output.stems ist keine Liste');
  }
  for (const stem of output.stems) {
    if (!stem || typeof stem !== 'object') {
      throw new RemoteProtocolError('REMOTE_MANIFEST_INVALID', 'Manifest enthält einen ungültigen Stem-Eintrag');
    }
    requireString(stem.id, 'output.stems[].id', manifest.jobId);
    requireString(stem.fileName, 'output.stems[].fileName', manifest.jobId);
    assertSafeRelative(stem.relativePath);
    requireString(stem.sha256, `output.stems[${stem.id}].sha256`, manifest.jobId);
  }
  return { ...manifest, output, attempts: manifest.attempts ?? 0 };
}

/**
 * Prüft die Vollständigkeit eines als COMPLETED gemeldeten Ergebnisses (§34).
 * Fehlt ein Stem, ist der Job **nicht** fertig – egal was im Status steht.
 */
export function verifyCompletedManifest(manifest: RemoteJobManifest): { ok: true } | { ok: false; code: string; message: string } {
  if (manifest.status !== 'COMPLETED') {
    return { ok: false, code: 'REMOTE_NOT_COMPLETED', message: `Job ${manifest.jobId} ist ${manifest.status}, nicht COMPLETED` };
  }
  const expected = manifest.engine.stems ?? [];
  const delivered = manifest.output?.stems ?? [];
  const deliveredIds = delivered.map((stem) => stem.id);
  const missing = expected.filter((stem) => !deliveredIds.includes(stem));
  if (missing.length > 0) {
    return {
      ok: false,
      code: 'REMOTE_OUTPUT_INCOMPLETE',
      message: `Job ${manifest.jobId} meldet COMPLETED, aber es fehlen: ${missing.join(', ')} (geliefert: ${deliveredIds.join(', ') || 'nichts'})`,
    };
  }
  const empty = delivered.filter((stem) => !Number.isFinite(stem.bytes) || stem.bytes <= 44);
  if (empty.length > 0) {
    return {
      ok: false,
      code: 'REMOTE_OUTPUT_EMPTY',
      message: `Job ${manifest.jobId}: Stem-Datei(en) ohne Inhalt: ${empty.map((stem) => stem.id).join(', ')}`,
    };
  }
  return { ok: true };
}

export function stemOutputFor(input: {
  id: StemId;
  fileName: string;
  relativePath: string;
  sha256: string;
  bytes: number;
  frames: number;
  sampleRate: number;
  channels: number;
  peak?: number;
}): RemoteStemOutput {
  return { ...input };
}

/** Ergebnissatz, den der Worker zusätzlich zum Manifest schreibt (menschenlesbar). */
export function buildResultDocument(manifest: RemoteJobManifest, extra: Record<string, unknown> = {}): string {
  return `${JSON.stringify(
    {
      schemaVersion: REMOTE_JOB_SCHEMA_VERSION,
      jobId: manifest.jobId,
      status: manifest.status,
      modelId: manifest.engine.modelId,
      profile: manifest.engine.profile,
      completedAtIso: new Date().toISOString(),
      stems: manifest.output?.stems ?? [],
      worker: manifest.worker,
      ...extra,
    },
    null,
    2
  )}\n`;
}

/**
 * Ablage-Layout der Fern-Jobs auf Google Drive (§16, §17).
 *
 * Bewusst ein flaches, selbsterklärendes Dateilayout: der Colab-Worker liest
 * es mit Standardmitteln (Drive-Mount + `os.listdir`), ohne dass irgendwo ein
 * Schema versteckt ist. Alle Pfade in dieser Datei sind **relativ zur
 * Job-Wurzel** und in POSIX-Schreibweise – so funktionieren sie auf Windows,
 * Linux und auf dem gemounteten Drive-Laufwerk gleichermaßen.
 *
 *   <root>/
 *     jobs/<jobId>/manifest.json        ← Quelle der Wahrheit für den Status
 *     jobs/<jobId>/input/<datei.wav>    ← Arbeitskopie (nie das Original)
 *     jobs/<jobId>/claim.json           ← Worker-Lease (wer rechnet gerade)
 *     jobs/<jobId>/cancel.flag          ← Editor: „brich ab“
 *     jobs/<jobId>/logs/worker.log      ← lesbares Worker-Log
 *     jobs/<jobId>/logs/worker.jsonl    ← strukturierte, korrelierbare Schritte
 *     jobs/<jobId>/output/<stem>.wav    ← Ergebnisse
 *     jobs/<jobId>/output/result.json   ← Ergebnisliste mit Hashes
 *     jobs/<jobId>/error.json           ← letzter Fehler (maschinenlesbar)
 */
import path from 'node:path';

export const REMOTE_JOBS_DIR = 'jobs';
export const REMOTE_MANIFEST_FILE = 'manifest.json';
export const REMOTE_CLAIM_FILE = 'claim.json';
export const REMOTE_CANCEL_FILE = 'cancel.flag';
export const REMOTE_ERROR_FILE = 'error.json';
export const REMOTE_INPUT_DIR = 'input';
export const REMOTE_OUTPUT_DIR = 'output';
export const REMOTE_LOGS_DIR = 'logs';
export const REMOTE_RESULT_FILE = 'result.json';
export const REMOTE_WORKER_LOG_FILE = 'worker.log';
export const REMOTE_WORKER_TRACE_FILE = 'worker.jsonl';

/** Erlaubte Job-Id-Form. Verhindert Pfad-Ausbrüche aus einem manipulierten Manifest. */
const JOB_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{7,63}$/;

export function isSafeJobId(jobId: unknown): jobId is string {
  return typeof jobId === 'string' && JOB_ID_PATTERN.test(jobId) && !jobId.includes('..');
}

/**
 * Prüft einen relativen Pfad aus einem Manifest, bevor er benutzt wird.
 * Ein fremdes Manifest darf den Editor niemals aus der Job-Wurzel führen.
 */
export function assertSafeRelative(relative: unknown): string {
  const value = typeof relative === 'string' ? relative : '';
  if (!value || value.startsWith('/') || value.includes('\\') || value.split('/').includes('..')) {
    throw new Error(`Unsicherer relativer Pfad im Manifest: ${JSON.stringify(relative)}`);
  }
  return value;
}

export function jobDir(jobId: string): string {
  if (!isSafeJobId(jobId)) throw new Error(`Ungültige Job-Id: ${JSON.stringify(jobId)}`);
  return `${REMOTE_JOBS_DIR}/${jobId}`;
}

export function jobManifestPath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_MANIFEST_FILE}`;
}

export function jobClaimPath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_CLAIM_FILE}`;
}

export function jobCancelPath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_CANCEL_FILE}`;
}

export function jobErrorPath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_ERROR_FILE}`;
}

export function jobInputPath(jobId: string, fileName: string): string {
  const safe = path.posix.basename(fileName).replace(/[^A-Za-z0-9._-]+/g, '_') || 'input.wav';
  return `${jobDir(jobId)}/${REMOTE_INPUT_DIR}/${safe}`;
}

export function jobOutputPath(jobId: string, stemFileName: string): string {
  const safe = path.posix.basename(stemFileName).replace(/[^A-Za-z0-9._-]+/g, '_') || 'stem.wav';
  return `${jobDir(jobId)}/${REMOTE_OUTPUT_DIR}/${safe}`;
}

export function jobResultPath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_OUTPUT_DIR}/${REMOTE_RESULT_FILE}`;
}

export function jobWorkerLogPath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_LOGS_DIR}/${REMOTE_WORKER_LOG_FILE}`;
}

export function jobWorkerTracePath(jobId: string): string {
  return `${jobDir(jobId)}/${REMOTE_LOGS_DIR}/${REMOTE_WORKER_TRACE_FILE}`;
}

/** Ein WAV-Name für einen Stem – dieselbe Konvention wie im lokalen Pfad. */
export function stemFileName(stemId: string): string {
  return `${stemId.replace(/[^A-Za-z0-9._-]+/g, '_')}.wav`;
}

/**
 * Verträge des High-Quality-Fernpfads (§15–§22).
 *
 * Warum diese Datei existiert
 * ---------------------------
 * Der HQ-Pfad (BS-RoFormer) läuft lokal auf einem Laptop in 60–90 Minuten pro
 * Track und ist damit für den Alltag unbrauchbar. Er bleibt der Qualitätspfad,
 * darf aber auf einem fremden Rechner (Google Colab) rechnen. Transportmittel
 * ist Google Drive – nicht als Datenbank, sondern als *Jobablage* (§16):
 *
 *   Editor ──Arbeitskopie+Manifest──▶ Drive ──▶ Colab-Worker
 *   Editor ◀──Stems+Status─────────── Drive ◀── Colab-Worker
 *
 * Der Editor bedient dabei niemals Colab von Hand. Alles, was beide Seiten
 * über diese Grenze austauschen, steht hier: Manifest, Status, Outputs,
 * Worker-Lease. Es ist bewusst ein **Dateiformat** (JSON + WAV), damit der
 * Worker auf der anderen Seite ein beliebiges Werkzeug sein kann – Python in
 * Colab, ein Node-Skript auf einem Studio-Rechner oder ein Testharness.
 *
 * Statuswerte sind die **vorhandenen** `JobStatus`-Werte aus `../types`
 * (PENDING/PREPARING/RUNNING/…/COMPLETED/FAILED/CANCELLED). Ein zweites,
 * konkurrierendes Statussystem gibt es ausdrücklich nicht (§14): was ein
 * Remote-Job zusätzlich weiß – Gerät, CPU-Rückfall, Worker – steht in eigenen
 * Feldern, nicht in neuen Statusnamen.
 */
import type { BackendKind, ComputeDevice, JobStatus, ModelFamily, QualityProfile, StemId } from '../types';
import type { RemoteJobTraceEvent } from '../transportTypes';
import type { RemoteJobFlow } from './dataFlow';
export type { RemoteJobTraceEvent } from '../transportTypes';
export type { RemoteJobFlow, RemoteFlowCheckpoint, RemoteFlowFact } from './dataFlow';

/** Version des Manifest-Schemas. Erhöhen, wenn Felder brechen (nicht additiv). */
export const REMOTE_JOB_SCHEMA_VERSION = 1;

/** Status eines Fern-Jobs – identisch zu {@link JobStatus} (§14). */
export type RemoteJobStatus = JobStatus;

/** Phasen, die nur im Fernpfad vorkommen (stehen in `phase`, nie im Status). */
export const REMOTE_PHASES = {
  created: 'Job erstellt – Arbeitskopie wird vorbereitet',
  uploading: 'Arbeitskopie wird zu Google Drive hochgeladen',
  waitingWorker: 'Wartet auf den externen Rechner (Google Drive)',
  fallbackCpu: 'Verarbeitung läuft – CPU-Fallback',
  runningGpu: 'Verarbeitung läuft – GPU',
  runningCpu: 'Verarbeitung läuft – CPU',
  downloading: 'Ergebnisse werden geladen',
  importing: 'Ergebnisse werden geprüft und importiert',
  completed: 'Stem-Separation abgeschlossen',
  cancelled: 'Abgebrochen',
  /**
   * Der Nutzer hat abgebrochen, aber die Ablage war nicht erreichbar: der
   * Editor liefert die Abbruchbitte bei jedem Poll nach, statt den Job still
   * fallen zu lassen (§37 – „geklickt und nichts passiert“ war der Fehler).
   */
  cancelPending: 'Abbruch angefordert – Meldung an die Jobablage wird wiederholt',
} as const;

export interface RemoteJobInput {
  /** Dateiname der Arbeitskopie (nie der Originalpfad des Nutzers). */
  fileName: string;
  /** Pfad **relativ** zur Job-Wurzel, posix-Schreibweise (Drive-tauglich). */
  relativePath: string;
  /** SHA-256 der Arbeitskopie; der Worker prüft ihn vor der Separation (§22). */
  sha256: string;
  bytes: number;
  durationSeconds: number;
  sampleRate: number;
  channels: number;
}

export interface RemoteJobEngineRef {
  /** Backend des Workers: `bs_roformer`, `python-torch`, … */
  backend: BackendKind | string;
  family: ModelFamily;
  /** Model-ID aus dem Katalog – der Worker lädt genau dieses Modell (§25). */
  modelId: string;
  profile: QualityProfile;
  /** Stems, die der Worker liefern muss (Reihenfolge = `stemOrder`). */
  stems: StemId[];
  /** Rechenort-Wunsch: `auto` = GPU wenn möglich, sonst CPU (§7). */
  device?: ComputeDevice;
  /** Checkpoint-Identität, damit der Worker keine „irgendein Modell“-Wahl trifft. */
  checkpoint?: { file: string; sha256?: string; url?: string };
  config?: { file: string; url?: string; sha256?: string };
  numOverlap?: number;
  chunkSizeSamples?: number;
}

export interface RemoteStemOutput {
  id: StemId;
  fileName: string;
  relativePath: string;
  sha256: string;
  bytes: number;
  frames: number;
  sampleRate: number;
  channels: number;
  peak?: number;
}

export interface RemoteWorkerLease {
  /** Stabile Worker-Kennung (`colab-<hostname>-<pid>` o. ä.). */
  id: string;
  claimedAt: number;
  /** Lebenszeichen des Workers; ohne frisches Herz gilt der Job als verwaist. */
  heartbeatAt?: number;
  host?: string;
  /** Tatsächlich benutztes Gerät (`cuda`, `cpu`, `dml`, …). */
  device?: string;
  cpuFallback?: boolean;
  fallbackReason?: string;
  version?: string;
  gpu?: string;
  torch?: string;
}

export interface RemoteJobManifest {
  schemaVersion: number;
  /** UUID – niemals nur der Dateiname (§18). */
  jobId: string;
  createdAt: number;
  updatedAt: number;
  /** Zusätzlich ISO-8601 für den Colab-Nutzer (Menschen lesen mit). */
  createdAtIso: string;
  updatedAtIso: string;
  status: RemoteJobStatus;
  phase?: string;
  percent?: number;
  /**
   * Idempotenzschlüssel (§19): identische Arbeit (gleicher Input-Hash, gleiches
   * Modell, gleiches Profil) darf nicht zweimal gerechnet werden.
   */
  idempotencyKey: string;
  origin: { app: string; version: string; host?: string };
  input: RemoteJobInput;
  engine: RemoteJobEngineRef;
  output: {
    stems: RemoteStemOutput[];
    resultFile?: string;
  };
  worker?: RemoteWorkerLease;
  /** Vom Editor gesetzt; der Worker muss laufende Arbeit dann fallen lassen (§37). */
  cancelRequested?: boolean;
  /** Wie oft ein Worker diesen Job begonnen hat (Diagnose, §21 E). */
  attempts?: number;
  error?: { code: string; message: string; at?: number };
  /** Freitext für Support; keine Tokens, keine Zugangsdaten (§23). */
  notes?: string[];
}

/**
 * Lokaler, dauerhafter Zustand eines Fern-Jobs (`<root>/RemoteJobs/<jobId>.json`).
 *
 * Er überlebt den Editor-Neustart – genau dafür existiert er (§21 A, §32):
 * beim Start werden alle Einträge geladen und weiterverfolgt, statt einen
 * zweiten Job für dieselbe Datei zu erzeugen.
 */
export interface RemoteJobRecord {
  schemaVersion: number;
  jobId: string;
  createdAt: number;
  updatedAt: number;
  /** Zeitpunkt der letzten fachlichen Phase/Progress-Änderung (nicht jedes Polling). */
  phaseUpdatedAt?: number;
  /** Begrenzte, persistente Ablaufspur; wird nicht bei jedem Poll erweitert. */
  trace?: RemoteJobTraceEvent[];
  /**
   * Belege des Datenflusses (`src/stems/remote/dataFlow.ts`): wann hat der
   * Editor welche Station tatsächlich beobachtet? Überlebt den Neustart und
   * ist die Grundlage des Laufzettels im Statusfenster.
   */
  flow?: RemoteJobFlow;
  /** Anzeigename der Ablage zum Zeitpunkt des Starts (nur Anzeige, §23). */
  transportLabel?: string;
  /** Wurzel der Ablage zum Zeitpunkt des Starts (nur Anzeige, §23). */
  transportRoot?: string;
  /** Worker-Event-IDs für Deduplizierung, auch wenn ältere Trace-Zeilen rotiert wurden. */
  workerTraceIds?: string[];
  status: RemoteJobStatus;
  phase: string;
  percent: number;
  trackName: string;
  profile: QualityProfile;
  modelId: string;
  family: ModelFamily;
  backend: string;
  stems: StemId[];
  idempotencyKey: string;
  /** Arbeitskopie im Engine-Datenordner (nie das Original). */
  workingCopyPath: string;
  workingCopySha256: string;
  workingCopyBytes: number;
  durationSeconds: number;
  sampleRate: number;
  channels: number;
  /** Original (falls der Job aus einer Datei kam) + Integritätsnachweis. */
  originalPath?: string;
  originalSha256?: string;
  originalBytes?: number;
  originalMtimeMs?: number;
  originalUnchanged?: boolean;
  /** Lokaler Job (StemJobService), über den der Editor die Stems liest. */
  localJobId?: string;
  importedStems?: { id: StemId; filePath: string; bytes: number; sha256: string }[];
  worker?: RemoteWorkerLease;
  uploadedAt?: number;
  lastPollAt?: number;
  /**
   * Zuletzt veröffentlichter Job-Steckbrief. Er erlaubt es, einen
   * unterbrochenen Upload zu wiederholen, ohne die Job-Id oder den
   * Idempotenzschlüssel neu zu erfinden (§21 B). Es ist dieselbe Information
   * wie in `jobs/<jobId>/manifest.json` – nur lokal, damit der Editor sie
   * nach einem Neustart noch hat.
   */
  manifest?: RemoteJobManifest;
  /** Transportfehler in Folge – temporäre Netzprobleme sind kein Job-Fehler (§21 C). */
  transportErrors: number;
  transportDegraded?: boolean;
  cancelRequestedAt?: number;
  /**
   * `true`, solange die Abbruchbitte die Jobablage noch nicht erreicht hat.
   * Der Job bleibt dann in Verfolgung (nicht terminal!), damit ein späterer
   * Poll die Fahne nachliefert und der Nutzer eine Rückmeldung bekommt.
   */
  cancelPending?: boolean;
  attempts?: number;
  device?: ComputeDevice;
  cpuFallback?: boolean;
  fallbackReason?: string;
  workerPercent?: number;
  finishedAt?: number;
  error?: { code: string; message: string };
}

export interface RemoteTransportConfig {
  kind: 'folder' | 'rclone';
  /**
   * `folder`: Pfad zum Google-Drive-Sync-Ordner (oder rclone-Mount).
   * `rclone`: Remote-Ziel, z. B. `gdrive:airdox-stem-jobs`.
   * Es wird nur die Jobablage benutzt – keine Drive-Datenbank (§16).
   */
  root: string;
  /** Nur für `kind: 'rclone'`: abweichende rclone-Konfigurationsdatei. */
  configPath?: string;
  /** Nur für `kind: 'rclone'`: rclone-Binary (Default: PATH). */
  binary?: string;
}
